/* Zego Design System — bundled behaviour (generated by build-dist.py). */


/* ==== components/alert/alert.js ==== */
/*
 * ============================================================
 * ALERT — dismiss behaviour
 * ============================================================
 * Clicking .alert__close fades the parent .alert out and removes it.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="alert.js"></script>
 * ============================================================
 */

(function () {
  document.addEventListener('click', function (event) {
    var closeBtn = event.target.closest('.alert__close');
    if (!closeBtn) return;

    var alert = closeBtn.closest('.alert');
    if (!alert) return;

    var remove = function () { if (alert.isConnected) alert.remove(); };

    // Graceful fade, then remove (with a timeout fallback if the
    // transition doesn't fire, e.g. reduced-motion / display quirks).
    alert.style.transition = 'opacity 150ms ease';
    alert.style.opacity = '0';
    alert.addEventListener('transitionend', remove, { once: true });
    setTimeout(remove, 250);
  });
})();


/* ==== components/bottom-nav/bottom-nav.js ==== */
/*
 * ============================================================
 * BOTTOM NAV — interactivity
 * ============================================================
 * Single-select: clicking a tab makes it the active one (filled icon +
 * .bottom-nav__item--active + aria-current) and clears the others.
 *
 * Applies to every .bottom-nav on the page. Add data-static to a bar to
 * opt it out (e.g. a reference row that should show a fixed state).
 *
 * Each item must contain both glyphs so the icon can swap without JS
 * touching the markup:
 *   <span class="bottom-nav__icon">
 *     <span class="bottom-nav__glyph bottom-nav__glyph--line"><svg>…</svg></span>
 *     <span class="bottom-nav__glyph bottom-nav__glyph--fill"><svg>…</svg></span>
 *   </span>
 * ============================================================
 */
(function () {
  function activate(nav, item) {
    nav.querySelectorAll('.bottom-nav__item').forEach(function (it) {
      var on = it === item;
      it.classList.toggle('bottom-nav__item--active', on);
      if (on) it.setAttribute('aria-current', 'page');
      else it.removeAttribute('aria-current');
    });
  }

  function init(nav) {
    if (nav.dataset.bottomNavReady) return;      // guard against double-init
    nav.dataset.bottomNavReady = '1';
    nav.addEventListener('click', function (e) {
      var item = e.target.closest('.bottom-nav__item');
      if (!item || !nav.contains(item)) return;
      e.preventDefault();
      activate(nav, item);
    });
  }

  function boot() {
    document.querySelectorAll('.bottom-nav:not([data-static])').forEach(init);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();


/* ==== components/comparison-tile/comparison-tile.js ==== */
/*
 * ============================================================
 * COMPARISON TILE — selection behaviour
 * ============================================================
 * Keeps the .comparison-tile--active class in sync with the selected radio
 * across a group (tiles sharing the same radio `name`). Selecting one tile
 * activates it and deactivates the previously-active one.
 *
 * (The frame colour also updates on its own via :has(.radio__input:checked);
 * this handler additionally clears any stale --active force class so the
 * previously-active tile fully resets.)
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="comparison-tile.js"></script>
 * ============================================================
 */

(function () {
  document.addEventListener('change', function (event) {
    var input = event.target;
    if (!(input instanceof HTMLInputElement) || input.type !== 'radio') return;
    if (!input.closest('.comparison-tile') || !input.name) return;

    var group = document.querySelectorAll(
      '.comparison-tile .radio__input[name="' + (window.CSS && CSS.escape ? CSS.escape(input.name) : input.name) + '"]'
    );
    if (group.length < 2) return; // only manage real multi-option groups

    group.forEach(function (radio) {
      var tile = radio.closest('.comparison-tile');
      if (tile) tile.classList.toggle('comparison-tile--active', radio.checked);
    });
  });
})();


/* ==== components/date-picker/date-picker.js ==== */
/*
 * ============================================================
 * DATE PICKER — render + navigation + selection
 * ============================================================
 * Renders each .date-picker from its data attributes and wires the prev/next
 * month buttons and day selection.
 *
 *   data-year, data-month (0–11) — the visible month
 *   data-selected  "YYYY-M-D"    — the chosen day (M is 0–11)
 *   data-today     "YYYY-M-D"    — the day drawn with the "today" outline
 *
 * Weeks start on Monday. Selecting a day updates data-selected and re-renders.
 * Self-init via event delegation:  <script src="date-picker.js" defer></script>
 * ============================================================
 */
(function () {
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];
  var WEEKDAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

  function key(y, m, d) { return y + '-' + m + '-' + d; }

  function render(dp) {
    var year = parseInt(dp.getAttribute('data-year'), 10);
    var month = parseInt(dp.getAttribute('data-month'), 10);
    var selected = dp.getAttribute('data-selected') || '';
    var today = dp.getAttribute('data-today') || '';

    var title = dp.querySelector('.date-picker__title');
    if (title) title.textContent = MONTHS[month] + ' ' + year;

    var grid = dp.querySelector('.date-picker__grid');
    if (!grid) return;

    var firstDow = (new Date(year, month, 1).getDay() + 6) % 7;   // Mon = 0
    var daysInMonth = new Date(year, month + 1, 0).getDate();

    var cells = '';
    for (var i = 0; i < firstDow; i++) {
      cells += '<span class="date-picker__day date-picker__day--empty" aria-hidden="true"></span>';
    }
    for (var d = 1; d <= daysInMonth; d++) {
      var k = key(year, month, d);
      var cls = 'date-picker__day';
      if (k === selected) cls += ' date-picker__day--selected';
      if (k === today) cls += ' date-picker__day--today';
      var pressed = k === selected ? ' aria-pressed="true"' : '';
      cells += '<button type="button" class="' + cls + '" data-day="' + d + '"' + pressed + '>' + d + '</button>';
    }
    grid.innerHTML = cells;
  }

  function shiftMonth(dp, delta) {
    var year = parseInt(dp.getAttribute('data-year'), 10);
    var month = parseInt(dp.getAttribute('data-month'), 10) + delta;
    if (month < 0) { month = 11; year--; }
    else if (month > 11) { month = 0; year++; }
    dp.setAttribute('data-year', year);
    dp.setAttribute('data-month', month);
    render(dp);
  }

  document.addEventListener('click', function (event) {
    var prev = event.target.closest('.date-picker__prev');
    if (prev) { shiftMonth(prev.closest('.date-picker'), -1); return; }

    var next = event.target.closest('.date-picker__next');
    if (next) { shiftMonth(next.closest('.date-picker'), 1); return; }

    var day = event.target.closest('.date-picker__day[data-day]');
    if (day) {
      var dp = day.closest('.date-picker');
      dp.setAttribute('data-selected', key(
        parseInt(dp.getAttribute('data-year'), 10),
        parseInt(dp.getAttribute('data-month'), 10),
        parseInt(day.getAttribute('data-day'), 10)
      ));
      render(dp);
      return;
    }
  });

  function initAll() {
    document.querySelectorAll('.date-picker').forEach(render);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();


/* ==== components/detail-card/detail-card.js ==== */
/*
 * ============================================================
 * DETAIL CARD — Incident type select
 * ============================================================
 * Clicking the "Incident type" field (a DS Input styled as a trigger) opens
 * the Dropdown List component 4px below it. Choosing a Dropdown Item fills the
 * field and closes the menu. Click-outside and Escape close it too.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="detail-card.js" defer></script>
 * ============================================================
 */
(function () {
  function closeAll(except) {
    document.querySelectorAll('.detail-card__select--open').forEach(function (sel) {
      if (sel === except) return;
      sel.classList.remove('detail-card__select--open');
      var trigger = sel.querySelector('.detail-card__select-trigger');
      if (trigger) trigger.setAttribute('aria-expanded', 'false');
    });
  }

  function setView(el, view) {
    var card = el.closest('.detail-card');
    if (card) card.setAttribute('data-view', view);
    closeAll(null);
  }

  document.addEventListener('click', function (event) {
    // Mode switching: Save / Cancel → view, pencil → edit
    var save = event.target.closest('[data-dc-save]');
    if (save) { setView(save, 'view'); return; }
    var cancel = event.target.closest('[data-dc-cancel]');
    if (cancel) { setView(cancel, 'view'); return; }
    var edit = event.target.closest('[data-dc-edit]');
    if (edit) { setView(edit, 'edit'); return; }

    // Pick an option
    var item = event.target.closest('.detail-card__select-menu .dropdown-item');
    if (item) {
      var selFromItem = item.closest('.detail-card__select');
      var input = selFromItem.querySelector('.input');
      var label = item.querySelector('.dropdown-item__label');
      if (input) input.value = label ? label.textContent.trim() : item.textContent.trim();
      closeAll(null);
      return;
    }

    // Toggle the menu
    var trigger = event.target.closest('.detail-card__select-trigger');
    if (trigger) {
      var sel = trigger.closest('.detail-card__select');
      var isOpen = sel.classList.contains('detail-card__select--open');
      closeAll(sel);
      sel.classList.toggle('detail-card__select--open', !isOpen);
      trigger.setAttribute('aria-expanded', String(!isOpen));
      return;
    }

    // Click outside
    closeAll(null);
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') closeAll(null);
  });
})();


/* ==== components/discount-code/discount-code.js ==== */
/*
 * ============================================================
 * DISCOUNT CODE — apply / error / remove behaviour
 * ============================================================
 * Each .discount-code holds a form and a hidden applied banner, switched via a
 * data-state attribute ("default" | "error" | "applied").
 *
 *   - Apply: if the entered code matches the valid code (data-code, default
 *     "ZEGO22", case-insensitive) → applied; otherwise → error.
 *   - Remove: clears the field and returns to default.
 *   - Editing the field after an error clears the error.
 *
 * Pair with input.js so the clear (×) button empties the field. Self-init via
 * event delegation:  <script src="discount-code.js" defer></script>
 * ============================================================
 */
(function () {
  function setState(dc, state) {
    dc.setAttribute('data-state', state);
    var field = dc.querySelector('.input-field');
    if (field) field.classList.toggle('input-field--error', state === 'error');
  }

  document.addEventListener('click', function (event) {
    var apply = event.target.closest('.discount-code__apply');
    if (apply) {
      var dc = apply.closest('.discount-code');
      if (!dc) return;
      var input = dc.querySelector('.input');
      var value = (input && input.value || '').trim();
      if (!value) { if (input) input.focus(); return; }
      var valid = (dc.getAttribute('data-code') || 'ZEGO22').toUpperCase();
      setState(dc, value.toUpperCase() === valid ? 'applied' : 'error');
      return;
    }

    var remove = event.target.closest('.discount-code__remove');
    if (remove) {
      var card = remove.closest('.discount-code');
      if (!card) return;
      var field = card.querySelector('.input');
      if (field) field.value = '';
      setState(card, 'default');
      return;
    }
  });

  // Editing after an error clears the error (also catches input.js clears)
  document.addEventListener('input', function (event) {
    var input = event.target.closest('.discount-code .input');
    if (!input) return;
    var dc = input.closest('.discount-code');
    if (dc && dc.getAttribute('data-state') === 'error') setState(dc, 'default');
  });
})();


/* ==== components/extra-cover/extra-cover.js ==== */
/*
 * Extra Cover — add / remove toggle
 * Clicking .extra-cover__add toggles the card's added state: it reveals the
 * "Added" badge, flips the button from primary "Add" to secondary "Added"
 * (with a tick) and back.
 */
(function () {
  'use strict';

  function setState(card, added) {
    card.classList.toggle('extra-cover--added', added);
    var btn = card.querySelector('.extra-cover__add');
    if (!btn) return;
    btn.classList.toggle('btn--primary', !added);
    btn.classList.toggle('btn--secondary', added);
    btn.setAttribute('aria-pressed', added ? 'true' : 'false');
    var label = btn.querySelector('.extra-cover__add-label');
    if (label) label.textContent = added ? 'Remove' : 'Add';
  }

  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.extra-cover__add');
    if (!btn) return;
    var card = btn.closest('.extra-cover');
    if (card) setState(card, !card.classList.contains('extra-cover--added'));
  });
})();


/* ==== components/input/input.js ==== */
/*
 * ============================================================
 * TEXT INPUT — clear button behaviour
 * ============================================================
 * Wires up the clear (×) button shown in the focused / error states.
 * Clicking .input__clear empties the field's .input, re-focuses it and
 * fires an `input` event so any listeners (validation, etc.) update.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="input.js"></script>
 * ============================================================
 */

(function () {
  // Keep focus on the field while the clear button is pressed. Without this,
  // the mousedown blurs the input, and clear buttons that are only revealed on
  // :focus-within (e.g. Search) get display:none before the click fires — so
  // the click is lost and the field never clears.
  document.addEventListener('mousedown', function (event) {
    if (event.target.closest('.input__clear')) event.preventDefault();
  });

  document.addEventListener('click', function (event) {
    var clearBtn = event.target.closest('.input__clear');
    if (!clearBtn) return;

    var field = clearBtn.closest('.input-field');
    var input = field && field.querySelector('.input');
    if (!input || input.disabled) return;

    input.value = '';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.focus();
  });
})();


/* ==== components/pagination/pagination.js ==== */
/*
 * Pagination Indicator — click to activate
 * Clicking a dot makes it the single active dot within its .pagination.
 * (Optional helper; the component is purely presentational without it.)
 */
(function () {
  'use strict';

  document.addEventListener('click', function (e) {
    var dot = e.target.closest('.pagination__dot');
    if (!dot) return;
    var group = dot.closest('.pagination');
    if (!group) return;
    group.querySelectorAll('.pagination__dot').forEach(function (d) {
      var active = d === dot;
      d.classList.toggle('pagination__dot--active', active);
      if (d.hasAttribute('aria-selected')) d.setAttribute('aria-selected', active ? 'true' : 'false');
    });
  });
})();


/* ==== components/sales-nav/sales-nav.js ==== */
/*
 * Sales Navigation — Help/Close toggle
 * Delegated click handler: pressing the toggle flips [data-expanded] on the
 * nearest .sales-nav, which shows/hides the Call-us dropdown and swaps the
 * pill between Help and Close (all styling handled in CSS).
 */
(function () {
  document.addEventListener('click', function (e) {
    var toggle = e.target.closest('.sales-nav__toggle');
    if (toggle) {
      var nav = toggle.closest('.sales-nav');
      if (!nav) return;
      var open = nav.getAttribute('data-expanded') === 'true';
      nav.setAttribute('data-expanded', open ? 'false' : 'true');
      toggle.setAttribute('aria-expanded', open ? 'false' : 'true');
      return;
    }
    // click outside an expanded nav closes it
    document.querySelectorAll('.sales-nav[data-expanded="true"]').forEach(function (nav) {
      if (!nav.contains(e.target)) {
        nav.setAttribute('data-expanded', 'false');
        var t = nav.querySelector('.sales-nav__toggle');
        if (t) t.setAttribute('aria-expanded', 'false');
      }
    });
  });
})();


/* ==== components/segment/segment.js ==== */
/*
 * ============================================================
 * SEGMENT CONTROL — selection behaviour
 * ============================================================
 * Clicking a segment selects it and deselects the others in the same control
 * (updating aria-selected). Disabled segments are ignored.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="segment.js"></script>
 * ============================================================
 */

(function () {
  document.addEventListener('click', function (event) {
    var item = event.target.closest('.segment__item');
    if (!item || item.disabled) return;

    var control = item.closest('.segment');
    if (!control) return;

    control.querySelectorAll('.segment__item').forEach(function (seg) {
      var selected = seg === item;
      seg.classList.toggle('segment__item--active', selected);
      seg.setAttribute('aria-selected', selected ? 'true' : 'false');
    });
  });
})();


/* ==== components/tab-bar/tab-bar.js ==== */
/*
 * ============================================================
 * TAB (tab bar) — selection behaviour
 * ============================================================
 * Clicking a tab in a role="tablist" bar makes it active and deactivates the
 * previously-active tab (updating aria-selected). Disabled tabs are ignored.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="tab-bar.js"></script>
 *
 * Scoped to .tabs[role="tablist"] so static state demos (a plain .tabs
 * without the role) aren't made interactive.
 * ============================================================
 */

(function () {
  document.addEventListener('click', function (event) {
    var tab = event.target.closest('.tab-item');
    if (!tab || tab.disabled) return;

    var bar = tab.closest('.tabs[role="tablist"]');
    if (!bar) return;

    bar.querySelectorAll('.tab-item').forEach(function (t) {
      var isActive = t === tab;
      t.classList.toggle('tab-item--active', isActive);
      t.setAttribute('aria-selected', isActive ? 'true' : 'false');
    });
  });
})();


/* ==== components/tier-card/tier-card.js ==== */
/*
 * Tier Card — group selection
 * Cards sharing a [data-tier-group] behave as a single-select set: clicking a
 * card's .tier-card__select makes it the active card and clears the others.
 * The button shows its data-label when unselected. When selected it shows
 * data-selected-label if present, otherwise "{data-label} selected".
 */
(function () {
  'use strict';

  function labelFor(btn) {
    return btn.getAttribute('data-label') || btn.textContent.trim().replace(/\s+selected$/i, '');
  }

  function selectedLabelFor(btn) {
    return btn.getAttribute('data-selected-label') || labelFor(btn) + ' selected';
  }

  function setLabel(btn, active) {
    if (btn) btn.textContent = active ? selectedLabelFor(btn) : labelFor(btn);
  }

  function selectCard(card) {
    var group = card.getAttribute('data-tier-group');
    var scope = card.parentElement || document;

    if (group) {
      scope.querySelectorAll('.tier-card[data-tier-group="' + group + '"]').forEach(function (c) {
        var active = c === card;
        c.classList.toggle('tier-card--active', active);
        setLabel(c.querySelector('.tier-card__select'), active);
      });
    } else {
      card.classList.toggle('tier-card--active');
      setLabel(card.querySelector('.tier-card__select'), card.classList.contains('tier-card--active'));
    }
  }

  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.tier-card__select');
    if (!btn) return;
    var card = btn.closest('.tier-card');
    if (card) selectCard(card);
  });
})();


/* ==== components/tier-section/tier-section.js ==== */
/*
 * Tier Section — billing period pricing
 * The prices in each Tier Card are stored as the MONTHLY amount on
 * `.tier-card__price[data-monthly]`. Clicking a billing Segment item that
 * carries data-period ("annual" | "monthly") reprices every tier in that
 * section: annual = monthly × 12.
 */
(function () {
  'use strict';

  function fmt(n) { return '£' + n.toFixed(2); }

  function reprice(section, period) {
    section.querySelectorAll('.tier-card__price[data-monthly]').forEach(function (el) {
      var monthly = parseFloat(el.getAttribute('data-monthly'));
      if (isNaN(monthly)) return;
      el.textContent = period === 'annual' ? fmt(monthly * 12) : fmt(monthly);
    });
  }

  document.addEventListener('click', function (e) {
    var item = e.target.closest('.tier-section .segment__item[data-period]');
    if (!item) return;
    var section = item.closest('.tier-section');
    if (section) reprice(section, item.getAttribute('data-period'));
  });


  /* --------------------------------------------------------
     Mobile carousel ↔ pagination
     On the horizontal tier scroller, keep the pagination dot in sync with the
     centred card, and let a dot click scroll its card to centre.
     -------------------------------------------------------- */

  function centredIndex(scroller, cards) {
    var box = scroller.getBoundingClientRect();
    var mid = box.left + box.width / 2;
    var best = 0, bestDist = Infinity;
    cards.forEach(function (c, i) {
      var r = c.getBoundingClientRect();
      var dist = Math.abs(r.left + r.width / 2 - mid);
      if (dist < bestDist) { bestDist = dist; best = i; }
    });
    return best;
  }

  function initCarousel(section) {
    var scroller = section.querySelector('.tier-section__tiers');
    var pager = section.querySelector('.tier-section__pagination');
    if (!scroller || !pager) return;
    var cards = Array.prototype.slice.call(scroller.querySelectorAll('.tier-card'));
    var dots = Array.prototype.slice.call(pager.querySelectorAll('.pagination__dot'));
    if (!cards.length || !dots.length) return;

    function sync() {
      var idx = centredIndex(scroller, cards);
      dots.forEach(function (d, i) {
        var on = i === idx;
        d.classList.toggle('pagination__dot--active', on);
        if (d.hasAttribute('aria-selected')) d.setAttribute('aria-selected', on ? 'true' : 'false');
      });
    }

    var ticking = false;
    scroller.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(function () { ticking = false; sync(); });
    });

    dots.forEach(function (d, i) {
      d.addEventListener('click', function () {
        if (cards[i]) cards[i].scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
      });
    });

    sync();
  }

  function initAll() {
    document.querySelectorAll('.tier-section').forEach(initCarousel);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();


/* ==== components/top-nav/top-nav.js ==== */
/*
 * ============================================================
 * TOP NAVIGATION / PLATFORM — expand + copy
 * ============================================================
 * Pressing Help (desktop) or the menu button (mobile) toggles [data-expanded]
 * on the nearest .top-nav, opening the dropdown and swapping Help⇄Close /
 * menu⇄close. The copy button copies the quote reference to the clipboard.
 * Click-outside and Escape close the panel.
 *
 * Self-init via event delegation:  <script src="top-nav.js" defer></script>
 * ============================================================
 */
(function () {
  function closeAll(except) {
    document.querySelectorAll('.top-nav[data-expanded="true"]').forEach(function (nav) {
      if (nav === except) return;
      nav.setAttribute('data-expanded', 'false');
      nav.querySelectorAll('[aria-expanded]').forEach(function (t) { t.setAttribute('aria-expanded', 'false'); });
    });
  }

  document.addEventListener('click', function (event) {
    // Copy the quote reference
    var copyBtn = event.target.closest('.top-nav__copy-btn');
    if (copyBtn) {
      var value = copyBtn.closest('.top-nav__copy').querySelector('.top-nav__copy-value');
      var text = value ? value.textContent.trim() : '';
      if (navigator.clipboard && text) navigator.clipboard.writeText(text).catch(function () {});
      copyBtn.classList.add('is-copied');
      copyBtn.setAttribute('aria-label', 'Copied');
      setTimeout(function () { copyBtn.classList.remove('is-copied'); copyBtn.setAttribute('aria-label', 'Copy'); }, 1500);
      return;
    }

    // Toggle the dropdown (Help pill or mobile menu button)
    var toggle = event.target.closest('.top-nav__help, .top-nav__menu');
    if (toggle) {
      var nav = toggle.closest('.top-nav');
      if (!nav) return;
      var open = nav.getAttribute('data-expanded') === 'true';
      closeAll(nav);
      nav.setAttribute('data-expanded', open ? 'false' : 'true');
      nav.querySelectorAll('[aria-expanded]').forEach(function (t) { t.setAttribute('aria-expanded', open ? 'false' : 'true'); });
      return;
    }

    // Click outside an open nav closes it
    document.querySelectorAll('.top-nav[data-expanded="true"]').forEach(function (nav) {
      if (!nav.contains(event.target)) {
        nav.setAttribute('data-expanded', 'false');
        nav.querySelectorAll('[aria-expanded]').forEach(function (t) { t.setAttribute('aria-expanded', 'false'); });
      }
    });
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') closeAll(null);
  });
})();


/* ==== components/trustpilot-reviews/trustpilot-reviews.js ==== */
/*
 * Trustpilot Reviews — carousel controls
 * Desktop prev/next arrows scroll the review track by a page; on mobile the
 * pagination dot follows the centred card and a dot click scrolls to it.
 */
(function () {
  'use strict';

  function centredIndex(track, cards) {
    var box = track.getBoundingClientRect();
    var mid = box.left + box.width / 2;
    var best = 0, bestDist = Infinity;
    cards.forEach(function (c, i) {
      var r = c.getBoundingClientRect();
      var dist = Math.abs(r.left + r.width / 2 - mid);
      if (dist < bestDist) { bestDist = dist; best = i; }
    });
    return best;
  }

  function init(widget) {
    var track = widget.querySelector('.tp-reviews__track');
    if (!track) return;
    var cards = Array.prototype.slice.call(track.querySelectorAll('.tp-review'));
    var dots = Array.prototype.slice.call(widget.querySelectorAll('.tp-reviews__pagination .pagination__dot'));

    function syncDots() {
      if (!dots.length) return;
      var idx = centredIndex(track, cards);
      dots.forEach(function (d, i) {
        var on = i === idx;
        d.classList.toggle('pagination__dot--active', on);
        if (d.hasAttribute('aria-selected')) d.setAttribute('aria-selected', on ? 'true' : 'false');
      });
    }

    var ticking = false;
    track.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(function () { ticking = false; syncDots(); });
    });

    widget.querySelectorAll('.tp-reviews__nav').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var dir = btn.getAttribute('data-dir') === 'prev' ? -1 : 1;
        track.scrollBy({ left: dir * Math.round(track.clientWidth * 0.9), behavior: 'smooth' });
      });
    });

    dots.forEach(function (d, i) {
      d.addEventListener('click', function () {
        if (cards[i]) cards[i].scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
      });
    });

    syncDots();
  }

  function initAll() { document.querySelectorAll('.tp-reviews').forEach(init); }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();
